    const totalQtyValue = items.reduce((sum, item) => sum + (item.quantity || 0), 0);

    const signatureImg = SIGNATURE_BASE64 ? `data:image/png;base64,${SIGNATURE_BASE64}` : '';

    const selectedUnitData = units.find(u => u.name === selectedUnit) || units[0];
